#!/bin/sh
set -eu

for tool in make "$CC" "$LD" python3 xorriso "${LIMINE_TOOL:-limine}"; do
    if ! command -v "$tool" >/dev/null 2>&1; then
        echo "Missing build dependency: $tool" >&2
        exit 1
    fi
done

# The checked-in atlas is generated by a Windows-only PowerShell script.
if [ ! -f src/drivers/ui_assets.h ]; then
    echo 'Missing src/drivers/ui_assets.h; restore the checked-in file before building.' >&2
    exit 1
fi

exec make -o src/drivers/ui_assets.h \
    CC64="$CC" ASM64="$CC" LD64="$LD" \
    CC32="$CC -m32" ASM32="$CC -m32" LD32="$LD" \
    PYTHON=python3 "$@" all
